CREATE TABLE [inv].[GoodIssueNote] (
    [GoodIssueNoteId] int NOT NULL,
    [CompanyId] int NULL,
    [GoodIssueNoteNumber] nvarchar(255) NULL,
    [GoodIssueNoteDate] date NULL,
    [WarehouseId] int NULL,
    [DepartmentId] int NULL,
    [Total] money NULL,
    [CreatedBy] nvarchar(100) NULL,
    [LastModifiedUserId] int NULL,
    [ApprovedUserId] int NULL,
    [CreatedDate] datetime NULL,
    [LastModifiedDate] datetime NULL,
    [ApprovedDate] datetime NULL,
    [Remarks] nvarchar(500) NULL,
    [CostCenter] varchar(100) NULL,
    [Location] varchar(100) NULL,
    PRIMARY KEY ([GoodIssueNoteId]),
    FOREIGN KEY ([WarehouseId]) REFERENCES [inv].[Warehouses]([WarehouseId]),
    FOREIGN KEY ([DepartmentId]) REFERENCES [adm].[Departments]([DepartmentId])
);

