CREATE TABLE [inv].[StockTakes] (
    [StockTakeId] int NOT NULL,
    [CompanyId] int NULL,
    [DocNumber] varchar(50) NOT NULL,
    [DocDate] date NOT NULL,
    [TypeEnum] tinyint NULL,
    [StatusEnum] tinyint NULL,
    [WarehouseId] int NULL,
    [Remarks] nvarchar(1000) NULL,
    [TxnWorkFlowId] int NULL,
    [CreationDate] datetime NULL,
    [SubmittedDate] datetime NULL,
    [ExpiryDate] datetime NULL,
    [CreatedUserId] int NULL,
    [ModifiedUserId] int NULL,
    [TempId] int NULL,
    [DepartmentID] int NULL,
    [CategoryID] int NULL,
    [SubCategoryID] int NULL,
    PRIMARY KEY ([StockTakeId]),
    FOREIGN KEY ([CompanyId]) REFERENCES [adm].[Companies]([CompanyId]),
    FOREIGN KEY ([WarehouseId]) REFERENCES [inv].[Warehouses]([WarehouseId]),
    FOREIGN KEY ([TxnWorkFlowId]) REFERENCES [cmn].[TxnWorkFlows]([TxnWorkFlowId])
);

CREATE TABLE [fin].[BankAdjustmentCostAllocations] (
    [BankAdjustmentCostAllocationId] int NOT NULL,
