    PRIMARY KEY ([BankAdjustmentCostAllocationId]),
    FOREIGN KEY ([BankAdjustmentLineId]) REFERENCES [fin].[BankAdjustmentLines]([BankAdjustmentLineId]),
    FOREIGN KEY ([DepartmentId]) REFERENCES [adm].[Departments]([DepartmentId]),
    FOREIGN KEY ([GoodsReceiveNoteId]) REFERENCES [inv].[GoodsReceiveNotes]([GoodsReceiveNoteId])
);

