CREATE TABLE [prc].[SubContractOrderLines] (
    [SubContractOrderLineId] int NOT NULL,
    [SubContractOrderId] int NULL,
    [SalesOrderLineId] int NULL,
    [ProductId] int NULL,
    [BillOfMaterialId] int NULL,
    [BaseUnitOfMeasureId] int NULL,
    [DocUnitOfMeasureId] int NULL,
    [TypeEnum] tinyint NULL,
    [Quantity] int NULL,
    [QuantityInBase] bigint NULL,
    [ExpectedDeliveryDate] date NULL,
    [DeliveryDate] date NULL,
    [DueDate] date NULL,
    [Remarks] nvarchar(1000) NULL,
    [CreationDate] datetime NULL,
    [SubmittedDate] datetime NULL,
    [ExpiryDate] datetime NULL,
    [CreatedUserId] int NULL,
    [ModifiedUserId] int NULL,
    [TempId] int NULL,
    PRIMARY KEY ([SubContractOrderLineId]),
    FOREIGN KEY ([SubContractOrderId]) REFERENCES [prc].[SubContractOrders]([SubContractOrderId]),
    FOREIGN KEY ([SalesOrderLineId]) REFERENCES [sales].[SalesOrderLines]([SalesOrderLineId]),
    FOREIGN KEY ([ProductId]) REFERENCES [inv].[Products]([ProductId]),
    FOREIGN KEY ([BillOfMaterialId]) REFERENCES [man].[BillOfMaterials]([BillOfMaterialId]),
    FOREIGN KEY ([BaseUnitOfMeasureId]) REFERENCES [inv].[UnitOfMeasures]([UnitOfMeasureId]),
    FOREIGN KEY ([DocUnitOfMeasureId]) REFERENCES [inv].[UnitOfMeasures]([UnitOfMeasureId])
);

CREATE TABLE [inv].[GoodIssueNoteLines] (
    [GoodIssueNoteDetailId] int NOT NULL,
    [GoodIssueNoteId] int NOT NULL,
    [ProductId] int NULL,
    [Price] money NOT NULL,
    [Quantity] decimal NOT NULL,
    [LineTotal] decimal NULL,
    [Description] varchar(255) NULL,
    [ProductCode] varchar(255) NULL,
    PRIMARY KEY ([GoodIssueNoteDetailId]),
    FOREIGN KEY ([GoodIssueNoteId]) REFERENCES [inv].[GoodIssueNote]([GoodIssueNoteId]),
    FOREIGN KEY ([ProductId]) REFERENCES [inv].[Products]([ProductId])
);

