CREATE TABLE [prc].[SubContractOrders] (
    [SubContractOrderId] int NOT NULL,
    [CompanyId] int NULL,
    [DepartmentId] int NULL,
    [SupplierId] int NULL,
    [CustomerId] int NULL,
    [DocNumber] varchar(50) NOT NULL,
    [DocDate] date NOT NULL,
    [RefDocNumber] varchar(50) NULL,
    [TypeEnum] tinyint NULL,
    [StatusEnum] tinyint NULL,
    [ProductId] int NULL,
    [DocUnitOfMeasureId] int NULL,
    [BillOfMaterialId] int NULL,
    [Quantity] int NULL,
    [DeliveryAddress] nvarchar(255) NULL,
    [Remarks] nvarchar(1000) NULL,
    [CreationDate] datetime NULL,
    [SubmittedDate] datetime NULL,
    [ExpiryDate] datetime NULL,
    [CreatedUserId] int NULL,
    [ModifiedUserId] int NULL,
    [TempId] int NULL,
    PRIMARY KEY ([SubContractOrderId]),
    FOREIGN KEY ([CompanyId]) REFERENCES [adm].[Companies]([CompanyId]),
    FOREIGN KEY ([DepartmentId]) REFERENCES [adm].[Departments]([DepartmentId]),
    FOREIGN KEY ([SupplierId]) REFERENCES [prc].[Suppliers]([SupplierId]),
    FOREIGN KEY ([CustomerId]) REFERENCES [sales].[Customers]([CustomerId]),
    FOREIGN KEY ([ProductId]) REFERENCES [inv].[Products]([ProductId]),
    FOREIGN KEY ([DocUnitOfMeasureId]) REFERENCES [inv].[UnitOfMeasures]([UnitOfMeasureId]),
    FOREIGN KEY ([BillOfMaterialId]) REFERENCES [man].[BillOfMaterials]([BillOfMaterialId])
