CREATE TABLE [inv].[StockTakeLines] (
    [StockTakeLineId] int NOT NULL,
    [StockTakeId] int NULL,
    [ProductId] int NULL,
    [UnitCost] money NULL,
    [UnitOfMeasureId] int NOT NULL,
    [OnHandQuantity] decimal NULL,
    [PhysicalQuantity] decimal NULL,
    [Remarks] varchar(200) NULL,
    [ExpiryDate] datetime NULL,
    [TempId] int NULL,
    [LotNumber] varchar(50) NULL,
    [BatchNumber] varchar(50) NULL,
    [SerialNumber] varchar(50) NULL,
    [AllocatedQuantity] decimal NULL,
    [CreationDate] datetime NULL,
    [CreatedUserId] int NULL,
    [ModifiedUserId] int NULL,
    [LastSelling] money NULL,
    PRIMARY KEY ([StockTakeLineId]),
    FOREIGN KEY ([StockTakeId]) REFERENCES [inv].[StockTakes]([StockTakeId]),
    FOREIGN KEY ([ProductId]) REFERENCES [inv].[Products]([ProductId])
);

CREATE TABLE [fin].[Accounts] (
    [AccountId] int NOT NULL,
    [CompanyId] int NULL,
    [EmployeeId] int NULL,
    [IsGeneral] bit NULL,
    [TypeEnum] tinyint NULL,
    [AccountName] nvarchar(50) NULL,
    [CurrencyId] int NULL,
    [IOUEnabled] bit NULL,
    [BankCode] varchar(50) NULL,
    [BankAccountNumber] varchar(50) NULL,
    [BankBranch] varchar(50) NULL,
    [AccountTypeEnum] tinyint NULL,
    [MultiCurrencyEnabled] bit NULL,
    [ODLimit] money NULL,
    [SWIFTCode] varchar(50) NULL,
    [StreetAddress] nvarchar(255) NULL,
    [CreationDate] datetime NULL,
    [CreatedUserId] int NULL,
    [ModifiedUserId] int NULL,
    [ExpiryDate] datetime NULL,
    [TempId] int NULL,
    [BankName] nvarchar(100) NULL,
    PRIMARY KEY ([AccountId]),
    FOREIGN KEY ([CompanyId]) REFERENCES [adm].[Companies]([CompanyId]),
    FOREIGN KEY ([EmployeeId]) REFERENCES [hr].[Employees]([EmployeeId]),
    FOREIGN KEY ([CurrencyId]) REFERENCES [adm].[Currencies]([CurrencyId])
);

